package com.neu.riketiku.shijuan;
import com.neu.riketiku.renzheng.RenZhengYeWuYiChang;import com.neu.riketiku.tiku.QuestionDisplayTextNormalizer;import java.math.*;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import tools.jackson.core.type.TypeReference;import tools.jackson.databind.ObjectMapper;
@Service public class PaperService{private final JdbcTemplate jdbc;private final QuestionDisplayTextNormalizer textNormalizer;private final ObjectMapper mapper=new ObjectMapper();public PaperService(JdbcTemplate jdbc,QuestionDisplayTextNormalizer textNormalizer){this.jdbc=jdbc;this.textNormalizer=textNormalizer;}
@Transactional public PaperDtos.Paper save(long userId,PaperDtos.Save request){long teacher=teacher(userId,request.subjectId());if(!Set.of("MANUAL","RULE").contains(request.mode())||request.items().stream().map(PaperDtos.ItemInput::questionId).distinct().count()!=request.items().size())bad("PAPER_ITEMS_INVALID","试卷题目不合法");validateQuestions(request.subjectId(),request.items().stream().map(PaperDtos.ItemInput::questionId).toList());jdbc.update("INSERT INTO shi_juan(chuang_jian_jiao_shi_id,ke_mu_id,shi_juan_ming_cheng,zu_juan_mo_shi) VALUES (?,?,?,?)",teacher,request.subjectId(),request.name().trim(),request.mode());long id=jdbc.queryForObject("SELECT LAST_INSERT_ID()",Long.class);int order=1;BigDecimal total=BigDecimal.ZERO;for(var item:request.items()){jdbc.update("INSERT INTO shi_juan_ti_mu(shi_juan_id,ti_mu_id,ti_mu_shun_xu,fen_zhi) VALUES (?,?,?,?)",id,item.questionId(),order++,item.score());total=total.add(item.score());}jdbc.update("UPDATE shi_juan SET zong_fen=?,zhuang_tai='READY' WHERE id=?",total,id);return detail(userId,id);}
public PaperDtos.Paper rule(long userId,PaperDtos.Rule request){teacher(userId,request.subjectId());List<Object> args=new ArrayList<>();StringBuilder sql=new StringBuilder("SELECT DISTINCT q.id FROM ti_mu q");if(request.knowledgePointIds()!=null&&!request.knowledgePointIds().isEmpty()){sql.append(" JOIN ti_mu_zhi_shi_dian qp ON qp.ti_mu_id=q.id AND qp.zhi_shi_dian_id IN (").append(String.join(",",Collections.nCopies(request.knowledgePointIds().size(),"?"))).append(")");args.addAll(request.knowledgePointIds());}sql.append(" WHERE q.ke_mu_id=? AND q.zhuang_tai='PUBLISHED' AND q.yi_shan_chu=0 AND q.shi_fou_ke_zi_dong_pan_fen=1");args.add(request.subjectId());if(request.questionTypes()!=null&&!request.questionTypes().isEmpty()){sql.append(" AND q.ti_mu_lei_xing IN (").append(String.join(",",Collections.nCopies(request.questionTypes().size(),"?"))).append(")");args.addAll(request.questionTypes());}if(request.difficulties()!=null&&!request.difficulties().isEmpty()){sql.append(" AND q.nan_du IN (").append(String.join(",",Collections.nCopies(request.difficulties().size(),"?"))).append(")");args.addAll(request.difficulties());}sql.append(" ORDER BY RAND() LIMIT ?");args.add(request.count());List<Long> ids=jdbc.query(sql.toString(),(rs,row)->rs.getLong(1),args.toArray());if(ids.size()<request.count())throw new RenZhengYeWuYiChang("PAPER_POOL_INSUFFICIENT","符合规则的已发布题目还缺 "+(request.count()-ids.size())+" 道",HttpStatus.CONFLICT);BigDecimal each=request.totalScore().divide(BigDecimal.valueOf(request.count()),2,RoundingMode.DOWN),last=request.totalScore().subtract(each.multiply(BigDecimal.valueOf(request.count()-1)));List<PaperDtos.ItemInput> items=new ArrayList<>();for(int i=0;i<ids.size();i++)items.add(new PaperDtos.ItemInput(ids.get(i),i==ids.size()-1?last:each));return save(userId,new PaperDtos.Save(request.subjectId(),request.name(),"RULE",items));}
@Transactional(readOnly=true) public List<PaperDtos.ListItem> list(long userId){return jdbc.query("SELECT p.id,p.shi_juan_ming_cheng,p.zu_juan_mo_shi,p.zong_fen,p.zhuang_tai,COUNT(i.id) FROM shi_juan p JOIN jiao_shi_dang_an j ON j.id=p.chuang_jian_jiao_shi_id LEFT JOIN shi_juan_ti_mu i ON i.shi_juan_id=p.id WHERE j.yong_hu_id=? AND p.yi_shan_chu=0 GROUP BY p.id ORDER BY p.id DESC",(rs,row)->new PaperDtos.ListItem(rs.getLong(1),rs.getString(2),rs.getString(3),rs.getBigDecimal(4),rs.getString(5),rs.getInt(6)),userId);}
@Transactional(readOnly=true) public List<PaperDtos.QuestionOption> questions(long userId,long subjectId,Long pointId,String type,Integer difficulty,String keyword){teacher(userId,subjectId);List<Object>args=new ArrayList<>();StringBuilder sql=new StringBuilder("SELECT DISTINCT q.id,q.ti_mu_lei_xing,q.ti_gan,q.nan_du FROM ti_mu q");if(pointId!=null)sql.append(" JOIN ti_mu_zhi_shi_dian qp ON qp.ti_mu_id=q.id AND qp.zhi_shi_dian_id=? AND qp.yi_shan_chu=0");sql.append(" WHERE q.ke_mu_id=? AND q.zhuang_tai='PUBLISHED' AND q.yi_shan_chu=0");if(pointId!=null)args.add(pointId);args.add(subjectId);if(type!=null&&!type.isBlank()){sql.append(" AND q.ti_mu_lei_xing=?");args.add(type.trim());}if(difficulty!=null){sql.append(" AND q.nan_du=?");args.add(difficulty);}if(keyword!=null&&!keyword.isBlank()){sql.append(" AND q.ti_gan LIKE ?");args.add("%"+keyword.trim()+"%");}sql.append(" ORDER BY q.id DESC LIMIT 200");return jdbc.query(sql.toString(),(rs,row)->new PaperDtos.QuestionOption(rs.getLong(1),rs.getString(2),textNormalizer.normalize(rs.getString(3)),rs.getInt(4),points(rs.getLong(1))),args.toArray());}
@Transactional(readOnly=true) public PaperDtos.Paper detail(long userId,long id){Base b=jdbc.query("SELECT p.id,p.ke_mu_id,k.ke_mu_ming_cheng,p.shi_juan_ming_cheng,p.zu_juan_mo_shi,p.zong_fen,p.zhuang_tai FROM shi_juan p JOIN jiao_shi_dang_an j ON j.id=p.chuang_jian_jiao_shi_id JOIN ke_mu k ON k.id=p.ke_mu_id WHERE p.id=? AND j.yong_hu_id=? AND p.yi_shan_chu=0",(rs,row)->new Base(rs.getLong(1),rs.getLong(2),rs.getString(3),rs.getString(4),rs.getString(5),rs.getBigDecimal(6),rs.getString(7)),id,userId).stream().findFirst().orElseThrow(()->new RenZhengYeWuYiChang("PAPER_NOT_FOUND","试卷不存在或无权访问",HttpStatus.NOT_FOUND));var questions=jdbc.query("SELECT q.id,i.ti_mu_shun_xu,i.fen_zhi,q.ti_mu_lei_xing,q.ti_gan,q.nan_du,CAST(q.zheng_que_da_an AS CHAR),a.jie_xi_nei_rong FROM shi_juan_ti_mu i JOIN ti_mu q ON q.id=i.ti_mu_id JOIN ti_mu_jie_xi a ON a.ti_mu_id=q.id AND a.jie_xi_lei_xing='STANDARD' WHERE i.shi_juan_id=? ORDER BY i.ti_mu_shun_xu",(rs,row)->new PaperDtos.Question(rs.getLong(1),rs.getInt(2),rs.getBigDecimal(3),rs.getString(4),textNormalizer.normalize(rs.getString(5)),rs.getInt(6),options(rs.getLong(1)),rs.getString(7),rs.getString(8),points(rs.getLong(1))),id);return new PaperDtos.Paper(b.id(),b.subjectId(),b.subjectName(),b.name(),b.mode(),b.score(),b.status(),questions);}
private long teacher(long user,long subject){return jdbc.query("SELECT DISTINCT j.id FROM jiao_shi_dang_an j JOIN ren_ke_guan_xi r ON r.jiao_shi_id=j.id WHERE j.yong_hu_id=? AND j.zhuang_tai='ACTIVE' AND j.yi_shan_chu=0 AND r.ke_mu_id=? AND r.zhuang_tai='ACTIVE'",(rs,row)->rs.getLong(1),user,subject).stream().findFirst().orElseThrow(()->new RenZhengYeWuYiChang("PAPER_SUBJECT_FORBIDDEN","无权使用该学科组卷",HttpStatus.FORBIDDEN));}private void validateQuestions(long subject,List<Long> ids){if(ids.isEmpty())bad("PAPER_ITEMS_INVALID","试卷不能为空");String marks=String.join(",",Collections.nCopies(ids.size(),"?"));List<Object>a=new ArrayList<>();a.add(subject);a.addAll(ids);Long n=jdbc.queryForObject("SELECT COUNT(*) FROM ti_mu WHERE ke_mu_id=? AND id IN ("+marks+") AND zhuang_tai='PUBLISHED' AND yi_shan_chu=0",Long.class,a.toArray());if(n!=ids.size())bad("PAPER_QUESTION_FORBIDDEN","试卷包含未发布或跨科题目");}private List<PaperDtos.Option>options(long id){return jdbc.query("SELECT xuan_xiang_biao_shi,xuan_xiang_nei_rong FROM ti_mu_xuan_xiang WHERE ti_mu_id=? AND yi_shan_chu=0 ORDER BY pai_xu",(rs,row)->new PaperDtos.Option(rs.getString(1),rs.getString(2)),id);}private List<String>points(long id){return jdbc.query("SELECT p.zhi_shi_dian_ming_cheng FROM ti_mu_zhi_shi_dian qp JOIN zhi_shi_dian p ON p.id=qp.zhi_shi_dian_id WHERE qp.ti_mu_id=? AND qp.yi_shan_chu=0 ORDER BY qp.pai_xu",(rs,row)->rs.getString(1),id);}private void bad(String c,String m){throw new RenZhengYeWuYiChang(c,m,HttpStatus.BAD_REQUEST);}private record Base(long id,long subjectId,String subjectName,String name,String mode,BigDecimal score,String status){} }
